Layer Control Prompt design Confidentiality instruction (weak alone) Output filter Detect system prompt fragments in responses Access control System prompts not in client-side code Logging Redact prompt content; log only prompt ID + version Monitoring Alert on extraction attempt patterns <pre><code>LEAKAGE_PATTERNS = [
  r"you are a",
  r"your instructions",
  r"system prompt",
  r"CONFIDENTIAL",
  # Add fragments unique to your system prompt
]


def detect_prompt_leakage(response: str, system_prompt: str) -&gt; bool:
  for pattern in LEAKAGE_PATTERNS:
    if re.search(pattern, response, re.IGNORECASE):
      return True
  # Fuzzy match against system prompt fragments
  prompt_fragments = extract_ngrams(system_prompt, n=5)
  for fragment in prompt_fragments:
    if fragment.lower() in response.lower():
      return True
  return False
